export function getTreeIdentificationFallback(species: string, title?: string): TreeIdentificationInfo | null {
  if (TREE_IDENTIFICATION_TRAITS[species]) return TREE_IDENTIFICATION_TRAITS[species];
  const hay = `${species} ${title || ''}`.toLowerCase();
  for (const [key, val] of Object.entries(TREE_IDENTIFICATION_TRAITS)) {
    if (hay.includes(key.toLowerCase())) return val;
  }
  return null;
}

