  return baseList.map((entry) => {
    const info = getTreeIdentificationFallback(entry.payload.species, entry.title);
    const shouldBeTree =
      entry.payload.isTree ||
      entry.payload.group === 'Gehölze' ||
      entry.payload.group === 'Nüsse' ||
      (entry.payload.group === 'Obst & Beeren' && !/erdbeere/i.test(entry.payload.species));
    if (!info && !shouldBeTree) return entry;
    return {
      ...entry,
      payload: {
        ...entry.payload,
        isTree: shouldBeTree || entry.payload.isTree,
        leafShape: entry.payload.leafShape || info?.leafShape,
        barkAndBuds: entry.payload.barkAndBuds || info?.barkAndBuds,
        identificationTraits: entry.payload.identificationTraits || info?.identificationTraits,
        practicalUses: entry.payload.practicalUses || info?.practicalUses,
      },
    };
  });
