        instructions: 'Pilze geputzt in einer Pfanne mit 1 EL Olivenöl und Thymian scharf anbraten (bei Wildpilzen mind. 15 Min. durchgaren!) und beiseitestellen. Im breiten Topf fein gewürfelte Schalotten in Öl glasig dünsten, Risottoreis 2 Min. mitrösten, bis die Körner an den Rändern glasig sind. Mit Weißwein ablöschen und vollständig einkochen lassen. Kellenweise heiße Brühe zugeben und unter regelmäßigem Rühren einköcheln, bis der Reis nach 18–20 Min. cremig, aber noch mit leichtem Biss („all’onda“) ist. Topf vom Herd nehmen, die gebratenen Pilze, kalte Butterwürfel und frisch geriebenen Parmesan kräftig unterrühren („Mantecatura“), 2 Min. zugedeckt ruhen lassen und mit Petersilie servieren.',
