          '• NIEMALS Eier vor der Lagerung abwaschen! Frisch gelegte Eier besitzen eine hauchdünne natürliche Schutzschicht (Cuticula), die Keime abhält. Trockene Verschmutzungen nur behutsam mit weichem Tuch/Schwamm trocken abreiben; stark verschmutzte Eier getrennt sofort kühl stellen und zügig durcherhitzt verbrauchen.\n• Lagerposition & Temperatur: Immer mit der spitzen Seite nach unten in sauberen Eierkartons lagern — so bleibt die Luftkammer oben stabil und die Keimscheibe steigt nicht an die Schale. Die ersten ~18 Tage kühl/speisekammergerecht (~10–15 °C), spätestens ab Tag 18–20 im Kühlschrank (4–7 °C) halten. Ab Tag 21 (bzw. bei warm gelagerten Eiern) nur noch vollständig durcherhitzt verwenden (~4 Wochen Gesamtlagerdauer bei sauberer Schale).\n• Schwimmtest im Wasserglas: Ganz frische Eier liegen waagerecht am Boden; 2–3 Wochen alte Eier richten sich schräg auf; oben treibende Eier wegen großer Luftkammer verwerfen (nicht verzehren!).',
