        content:
          'Ein guter Hanggarten fühlt sich nicht steil und anstrengend an, sondern lädt zum Hochschlendern ein:\n• SCHLÄNGELWEGE STATT STEILER TREPPE: Eine gerade Treppe schnurstracks den Hang hoch wirkt hart und ist mit voller Schubkarre unpraktisch. Besser: Den Hauptweg in sanften Serpentinen (Diagonalen/Kurven) mit maximal 6–8 % Steigung oder als flache Stufen-Wege-Kombination (z.B. 3 flache Blockstufen, dann 2–3 m gerades Wegstück zum Durchschnaufen) anlegen!\n• SCHUBKARREN-TRICK AM HANG: Neben schmalen Gartentreppen eine ca. 35–45 cm breite schräge Rampe aus geriffelten Lärchenbohlen oder Kleinpflaster bauen — so fahrt ihr Kompost, Holz und Ernte mühelos nach oben und unten.\n• TERRASSIEREN MIT AUGENMASS: Lieber 2–3 mittelgroße, geschwungene Stufen (40–60 cm hoch) als eine einzige riesige 2-Meter-Mauer! Naturstein-Trockenmauern (z.B. Thüringer Schiefer/Grauwacke), Rundhölzer oder dicht bepflanzte Böschungsinseln wirken viel weicher und fügen sich ins Schwarzatal ein.\n• BLICKACHSEN & ZIELPUNKT OBEN SCHAFFEN: Weil man vom Haus nach oben blickt, braucht der Hang oben einen schönen Ankerpunkt: z.B. ein geschwungener Weiden-/Rosenbogen als „Tor“ zur oberen Wiese, ein einzelner charaktervoller Apfelbaum oder eine kleine Holzbank („Feierabend-Platz“) mit Blick über das Dach.\n• HANG-SITZPLATZ EINSCHNEIDEN: Eine halbkreisförmige kleine Plattform in den Hang einbauen, hinten von einer 50 cm Trockenmauer mit Lavendel/Thymian eingefasst — man sitzt wie in einem warmen Nest im Rücken geschützt!',
