        content:
          'Pflanzen am Hang brauchen ein gutes Wurzelnetz gegen Erosion — und müssen zur Wasserverteilung passen (oben trockener, unten feuchter!):\n1. HANGKRONE & SONNIGE BÖSCHUNG (eher trocken, windoffen — Tief- & Flächenwurzler!):\n   • Gehölze/Sträucher: Felsenbirne, Schlehe, Kornelkirsche, Wildrosen/Hagebutte (Rosa canina / rugosa), Haselnuss, Aronia, Lavendel, Rosmarin-Weide.\n   • Stauden/Bodendecker: Teppich-Thymian, Polster-Phlox, Großblättriger Storchschnabel (Geranium macrorrhizum — unverwüstlich!), Blaukissen, Schafgarbe, Sonnenhut (Echinacea), Blauschwingel-Gras, Katzenminze (Nepeta — blüht monatelang!).\n2. TROCKENMAUER-KRONE & STEINFUGEN (heiß, extrem durchlässig):\n   • Hauswurz (Sempervivum), Scharfer/Milder Mauerpfeffer (Sedum), Hängendes Zimbelkraut, Polster-Glockenblume, Schleifenblume (Iberis), kriechender Thymian.\n3. HALBSCHATTIGER / NORDSEITIGER HANG (frisch, kühl):\n   • Farn-Arten (Wurmfarn, Hirschzungenfarn), Funkien (Hosta), Kaukasusvergissmeinnicht (Brunnera), Purpurglöckchen (Heuchera), Lungenkraut, Wald-Storchschnabel, Akelei, Fingerhut (giftig — nicht für Kleinkinder/Hühnerauslauf!), Elfenblume (Epimedium — hält Schattenböschungen fest).\n4. HANGFUSS (nährstoff- und wasserreicher, mind. 1,5 m Abstand zur Hauswand):\n   • Rispenhortensie (Hydrangea paniculata — frosthart für Thüringen!), Taglilien (Hemerocallis), Frauenmantel (Alchemilla mollis — fängt Tautropfen wie Perlen!), Johannisbeeren, Rhabarber, Iris sibirica.\n• PFLANZ-TIPP AM STEILHANG: Jede Pflanze mit einer kleinen „Gießtasche“ (halbmondförmiger kleiner Erdwall auf der Talseite rund um den Wurzelballen) setzen und in den ersten 2 Jahren Hang mit Kokosmatte/Holzhäcksel schützen, bis die Wurzeln greifen.',
