        content:
          'Zeitlose Profi-Tricks, mit denen jeder Garten sofort spannender, gemütlicher und trotzdem pflegeleichter wird:\n• GARTENRÄUME STATT „ALLES AUF EINEN BLICK“: Ein Grundstück, das man von einer Ecke bis zur letzten komplett übersieht, wirkt kleiner und leerer. Teilt den Garten optisch mit einem Rosen-/Bohnen-Bogen, einer halbhohen Beerenhecke (Johannisbeere/Aronia), einem Sichtschutz aus Weidenruten oder schmalen Staudeninseln — so gibt es „um die Ecke“ immer etwas Neues zu entdecken!\n• DAS 3-SCHICHTEN-PRINZIP (Weniger Unkraut, Dauerblüte!):\n  1. Gerüst-Schicht (Höhe): Obstbäume, Sträucher, Kletterbögen, hohe Gräser.\n  2. Haupt-Schicht (Mitte): Blütenstauden wie Phlox, Sonnenhut, Taglilie, Lavendel, Rittersporn.\n  3. Bodendecker- & Zwiebel-Schicht (Unten): Storchschnabel, Walderdbeere, Thymian, Frauenmantel PLUS Frühlingszwiebeln (Schneeglöckchen, Krokus, Narzissen, Tulpen) dazwischen — so ist der Boden von März bis November bedeckt und Unkraut hat kaum Platz.\n• TAGESZEIT-SITZPLÄTZE: Statt nur einer einzigen großen Terrasse lohnt sich ein zweiter kleiner Platz (oft reicht eine Kiesfläche für 2 Stühle!): z.B. Frühstücksplatz in der Morgensonne, ein schattiger Sommer-Sitzplatz unter einem Obstbaum und die „Feierabend-Bank“ dort, wo abends die letzte Sonne hinfällt.\n• ESSBARE ZIERBEETE („Edible Landscaping“): Nutzgarten muss nicht wie ein grauer Acker aussehen! Roter Mangold, dunkelvioletter Grünkohl, blauer Borretsch, leuchtende Ringelblumen, lila Schnittlauchblüten, rankende Feuerbohnen und Erdbeeren als Beetkante sehen umwerfend aus — und landen abends im Topf.',
