        category: 'Pflanzenbau & Frühjahr',
        content:
          'Die wichtigsten Profi-Geheimnisse, damit aus zarten Sämlingen kompakte, bärenstarke Jungpflanzen werden:\n• VERGEILEN VERHINDERN („Licht vs. Wärme“-Gesetz!): Lange, dünne, blasse Stängel entstehen fast immer durch ZU VIEL WÄRME bei ZU WENIG LICHT (z.B. 22 °C über der Heizung am noch dunklen Märzfenster!).\n  – Pro-Tipp 1: Sobald der Keimling aus der Erde schaut, Temperatur auf ca. 14–18 °C senken (kühleres Schlafzimmer/Flurfenster!) und direkt hinter die Anzuchtschalen eine weiße Pappe oder Alufolie als Lichtreflektor stellen — verdoppelt die Lichtausbeute!\n  – Pro-Tipp 2: Mit einem kleinen Handfächer oder Streicheln sanft über die Tomaten-/Kohlspitzen fahren — mechanischer Reiz („Thigmomorphogenese“) lässt Stängel spürbar dicker und standfester wachsen!\n• TOMATEN-WURZELTRICK: Tomaten (im Gegensatz zu Paprika/Salat!) bilden am gesamten Stängel neue Wurzeln! Beim Pikieren und endgültigen Auspflanzen im Mai die unteren Keimblätter abknipsen und die Pflanze extra TIEF (oder bei zu langen Stielen waagerecht liegend in eine Rinne!) eingraben — sorgt für ein riesiges Wurzelsystem!\n• KOHL & SALAT GENAU UMGEKEHRT: Kopfsalat niemals zu tief setzen (das „Salatherz“ muss frei über der Erde sitzen, sonst fault es!). Kohl dagegen fest und bis knapp unter die Keimblätter setzen.\n• ABHÄRTEN VOR DEM AUSSETZEN (7–10 Tage): Vorzuchtpflanzen von der Fensterbank NIEMALS direkt in die pralle Mai-Sonne stellen (sonst verbrennen die Blätter weiß!). 1 Woche lang tagsüber erst schattig/windgeschützt rausstellen, dann langsam an Sonne & Wind gewöhnen.',
