        content:
          'Richtig gießen spart halb so viel Arbeit, bis zu 60 % Wasser und verhindert fast alle Pilzkrankheiten:\n• SELTENER, ABER TIEF DURCHDRINGEND: Tägliches kurzes „Drüberhuschen“ benetzt nur die obersten 2 cm — die Wurzeln bleiben faul an der Oberfläche und verdursten bei der nächsten Hitzewelle! Besser 1–2x pro Woche richtig satt wässern (~10–15 Liter pro m²), damit die Wurzeln tief nach unten wachsen.\n• DER OLLA-TONTOPF-HACK (Genial für Hochbeet & Urlaub!): Einen unglasierten, porösen Terrakotta-Blumentopf nehmen, das Bodenloch mit Silikon/Korken/Ton verschließen und bis zum Rand im Gemüsebeet eingraben. Mit Wasser füllen und Untersetzer als Deckel drauf (gegen Verdunstung & Mücken): Durch die poröse Wand zieht sich jede Tomaten-/Zucchiniwurzel genau so viel Wasser, wie sie braucht — 0 % Verdunstung, 3–5 Tage Gießpause möglich!\n• KALTEN ZISTERNEN-SCHOCK VERMEIDEN: Gurken, Paprika, Melonen & Tomaten hassen eiskaltes Wasser direkt aus dem Schlauch/Brunnen (Wurzeln stellen stundenlang die Aufnahme ein!). Wasser immer erst in der schwarzen Regentonne oder Gießkanne ein paar Stunden anwärmen lassen.\n• MORGENS STATT ABENDS GIESSEN: Abends gegossene Beete bleiben die ganze kühle Nacht nass — eine Einladung für Nacktschnecken und Pilze (Echter/Falscher Mehltau, Braunfäule). Immer morgens direkt an den Wurzelbereich (nie über die Blätter!) gießen.',
