          'Was in einem scheinbar stillen Gartenboden und zwischen euren Beeten wirklich abläuft, ist reines Sci-Fi-Wunder:\n1. DAS „WOOD WIDE WEB“ (Mykorrhiza-Netzwerk): Rund 90 % aller Garten- & Wildpflanzen gehen unter der Erde eine Partnerschaft mit feinsten Pilzfäden (Mykorrhiza) ein. Die Pflanze liefert dem Pilz Zucker aus Sonnenlicht — der Pilz erschließt ein bis zu 100x größeres Bodenvolumen und liefert Wasser, Phosphor und Spurenelemente zurück! Tiefes Umgraben mit dem Spaten zerschneidet dieses unsichtbare Internet jedes Jahr aufs Neue.\n2. PFLANZEN RUFEN LEIBWÄCHTER PER DUFT: Werden Kohl- oder Apfelblätter von Raupen angeknabbert, setzen die Pflanzen spezifische flüchtige Duftstoffe frei. Winzige Schlupfwespen und Florfliegen riechen diesen Hilferuf über viele Meter, fliegen gezielt den „Tatort“ an und legen ihre Eier genau in die Schädlinge — gleichzeitig warnen Nachbarpflanzen vorab ihre Blätter und fahren Bitterstoffe hoch!\n3. DIE TAGETES-WURZELWAFFE: Die fröhlichen orangefarbenen Studentenblumen (Tagetes) sondern über ihre Wurzeln Schwefelverbindungen (Thiophene) ab, die bodenlebende Fadenwürmer (Nematoden) rund um Tomaten, Möhren und Erdbeeren massiv reduzieren!\n4. REGENWURM-RECHNUNG: In einem Quadratmeter unumgegrabenen, gemulchten Gartenboden arbeiten 150–400 Regenwürmer. Ihr Kot (Wurmhumus) enthält etwa 5x mehr direkt pflanzenverfügbaren Stickstoff, 7x mehr Phosphor und 11x mehr Kalium als die normale umgebende Gartenerde!',
