        content:
          'Gratis-Supermittel aus eigenen Gartenkräutern und der Küche — richtig dosiert unschlagbar:\n• BRENNNESSELJAUCHE (Der Stickstoff-Turbo für Starkzehrer):\n  – Rezept: 1 kg frische Brennnesseln (vor der Samenreife!) grob zerkleinern, in einen Kunststoff-/Holzeimer (KEIN Metall!) mit 10 L Regenwasser geben, luftig abdecken (Gitter gegen Insekten/Igel!) und täglich kräftig umrühren (bringt Sauerstoff rein).\n  – Nach ca. 10–14 Tagen (sobald nichts mehr schäumt) abseihen und zwingend **1:10 mit Wasser verdünnt** an die Wurzeln von Kohl, Tomaten, Kürbis & Lauch gießen (niemals über Blätter oder an Bohnen/Erbsen!).\n  – PRO-TIPP GEGEN GERUCH: Eine Handvoll Urgesteinsmehl oder 2–3 Tropfen Baldrianblütenextrakt bindet den Geruch fast komplett!\n• ACKERSCHACHTELHALM-BRÜHE (Kieselsäure-Schutzschild gegen Pilze):\n  – 1 kg frischen (oder 150 g getrockneten) Ackerschachtelhalm 24 Std. in 10 L Wasser einweichen, dann 30 Min. leicht köcheln, abkühlen lassen und **1:5 verdünnt** bei trockenem Wetter morgens auf Tomaten, Gurken, Erdbeeren & Rosen sprühen — die enthaltene Kieselsäure macht Zellwände so hart, dass Braunfäule & Mehltau kaum eindringen können!\n• ZIMT-PROTIP BEI AUSSAAT: Eine hauchdünne Prise echter Ceylon-Zimt auf feuchte Anzuchterde wirkt natürlich fungizid und stoppt die gefürchtete „Umfallkrankheit“ bei zarten Keimlingen!\n• KAFFEESATZ & EIERSCHALEN RICHTIG NUTZEN: Kaffeesatz niemals dick & nass aufs Beet kippen (schimmelt und verkrustet!) — erst trocknen und dünn streuen oder in den Kompost geben. Eierschalen bringen nur dann schnell Kalk, wenn man sie vorher trocknet und im Mörser/Mixer zu feinem Staub mahlt.',
