        content:
          'Zwei ideale, wetterfeste Rassen für das Mittelgebirgsklima im Schwarzatal:\n• VORWERK (Deutsche Traditionsrasse):\n  – Legeleistung: ~170–190 cremefarbene Eier/Jahr (ca. 55 g); legt auch im Spätherbst ordentlich weiter.\n  – Fleischleistung: Hahn ~2,5–3,0 kg, Henne ~2,0–2,5 kg — feines, kerniges Zweinutzungsfleisch.\n  – Verhaltensprofil: Lebhaft, äußerst geschickter Freiland-Futtersucher, aufmerksam gegen Greifvögel, ruhig im Umgang (wird mit etwas Geduld zahm); mäßig flugfreudig (Zaun ~1,2–1,5 m empfohlen), kaum Bruttrieb.\n  – Anfälligkeiten & Besonderheiten: Sehr robust, kaum krankheitsanfällig; geschützte alte Landrasse (GEH).\n• THÜRINGER BARTHUHN (Regionaler Schatz!):\n  – Legeleistung: ~160–180 weiße Eier/Jahr (ca. 53 g).\n  – Fleischleistung: Hahn ~2,0–2,5 kg, Henne ~1,5–2,0 kg — zarter Braten, Schwerpunkt eher Ei & Robustheit.\n  – Verhaltensprofil: Wachsam, fleißige Futtersucher, vertrauensvoll zum Halter, wenig Bruttrieb; fliegen mittelstark.\n  – Anfälligkeiten & Besonderheiten: Durch kleinen Kamm + dichten Backenbart extrem geschützt gegen Kamm-Erfrierungen im harten Thüringer Winter! Tipp: Bei matschigem Weichfutter gelegentlich Bart auf Verklebungen prüfen.',
