        content:
          'Die beiden wohl besten unkomplizierten Allrounder für Eier UND guten Braten:\n• BIELEFELDER KENNHUHN:\n  – Legeleistung: ~200–220 große hell- bis mittelbraune Eier/Jahr (60–65 g!) — ausgezeichnete Winterlegeleistung!\n  – Fleischleistung: Hahn ~3,0–4,0 kg, Henne ~2,5–3,25 kg — schnellwüchsig, sehr kräftiger, saftiger Fleischansatz.\n  – Verhaltensprofil: Ausgesprochen ruhig, sanftmütig, sehr zutraulich und kaum schreckhaft; praktisch flugunfähig (1 m Zaun reicht meist!); mäßiger Bruttrieb. Besonderheit: Kennfarbig (Hähne & Hennen am 1. Lebenstag anhand des Sperberflecks unterscheidbar!).\n  – Anfälligkeiten: Sehr winterhart und robust, neigt allerdings ab dem 2. Jahr bei zu viel Mais/Brot stark zur VERFETTUNG (Legeleistung bricht dann ein -> Futter rationiert geben!).\n• AMROCK:\n  – Legeleistung: ~200–220 cremefarbene bis hellbraune Eier/Jahr (ca. 58–60 g).\n  – Fleischleistung: Hahn ~3,0–4,0 kg, Henne ~2,5–3,0 kg — sehr gute Mast- & Schlachteigenschaften.\n  – Verhaltensprofil: Neugierig, freundlich, sehr menschenbezogen („schaut einem beim Graben zu“), kaum flugfreudig, geringer Bruttrieb.\n  – Anfälligkeiten: Ebenfalls leichte Neigung zum Verfetten im Alter; durch große Körpersubstanz flache Schlafstangen (max. 50–60 cm) nutzen.',
