        content:
          'Ideal, wenn entspannte, ruhige und zutrauliche Hühner ohne Ausbruchskünste gewünscht sind:\n• SUSSEX (Großrasse):\n  – Legeleistung: ~180–210 hellbraune bis gelbliche Eier/Jahr (ca. 55–60 g, gute Winterleger).\n  – Fleischleistung: Hahn ~3,0–4,0 kg, Henne ~2,5–3,0 kg — geschätztes, zartes weißes Tafelfleisch.\n  – Verhaltensprofil: Sehr friedlich, gemütlich, wird schnell handzahm; fliegt kaum (niedriger Zaun genügt), zuverlässige Glucken.\n  – Anfälligkeiten: Sehr kältehart! Wegen des hohen Gewichts nicht von hohen Stangen auf harten Stallboden springen lassen (Risiko für Ballenabszesse / „Bumblefoot“ -> dick einstreuen & flache Stangen!).\n• ORPINGTON:\n  – Legeleistung: ~160–180 hellbraune Eier/Jahr (ca. 55 g).\n  – Fleischleistung: Hahn ~4,0–4,5 kg, Henne ~3,0–3,5 kg — sehr breite Brust und üppiger Fleischansatz.\n  – Verhaltensprofil: Das „Sofakissen“ unter den Hühnern — extrem sanft, träge-gemütlich, flugunfähig, SEHR brutfreudig (hervorragende Glucke!).\n  – Anfälligkeiten: 1. Verfettet sehr schnell bei zu viel Leckerlis; 2. Dichtes Plüschgefieder saugt sich bei Dauerregen voll (trockener Unterstand wichtig) und verursacht im Hochsommer schneller Hitzestress -> viel Schatten anbieten!',
