        content:
          'Perfekt für alle, die besonders zutrauliche, ruhige Kaninchen mit Charakter suchen:\n• MEISSNER WIDDER (Alte sächsische GEH-Kulturrasse!):\n  – Leistung & Gewicht: Endgewicht ~4,5–5,5 kg; gute Fleischleistung (~55–58 % Ausbeute), kräftiger Körperbau, meist 6–8 Junge/Wurf und vorbildliche Muttereigenschaften.\n  – Verhaltensprofil: Eines der sanftmütigsten und menschenbezogensten Kaninchen überhaupt — ausgesprochen ruhig, neugierig, wenig schreckhaft (perfekt auch für ruhige Gartengruppen).\n  – Anfälligkeiten (Widder-spezifisch!): Durch die schweren Hängeohren („Behang“ 36–42 cm) ist der Gehörgang schlechter belüftet -> regelmäßig Ohreninnenseite auf bräunliche Krusten (Ohrräude / Psoroptes-Milben) kontrollieren! Außerdem in Gehegen keine engen Metall-Heuraufen mit spitzen Haken nutzen, in denen die langen Ohren hängenbleiben können.\n• DEUTSCHER KLEINWIDDER:\n  – Leistung & Gewicht: Kompakt (~3,0–3,5 kg Endgewicht, ~1,8–2,0 kg Küchengewicht), 5–7 Junge/Wurf — ideal für kleinere Haushalte.\n  – Verhaltensprofil: Gemütlich, verschmust, verspielt und sehr gut sozialisierbar.\n  – Anfälligkeiten: Ebenfalls Ohren regelmäßig checken; da Widder bei der Zucht leicht zu Zahnfehlstellungen bei zu kurzen Köpfen neigen können, auf seriöse Züchter mit normal langem Nasenprofil achten!',
