          'Wichtige Unterschiede bei beliebten Sonder- und Großrassen vor der Anschaffung:\n• BURGUNDER (Geheimtipp für Hofhaltung!):\n  – Leistung & Gewicht: ~4,25–5,0 kg, extrem frohwüchsig, hohe Schlachtausbeute (~58 %), 6–9 Junge/Wurf.\n  – Verhaltensprofil: Vital, freundlich, sehr ausgeglichen.\n  – Anfälligkeiten: Gering — zählt zu den robustesten Mittelrassen.\n• REX-KANINCHEN (Samtfell):\n  – Leistung & Gewicht: ~3,5–4,5 kg, feines Fleisch, 5–7 Junge/Wurf; ruhiges, angenehmes Temperament.\n  – Anfälligkeiten (KRITISCH!): Durch das fehlende lange Schutz-Deckhaar besitzen Rexe auch an den Pfotensohlen nur dünnes Samtfell -> SEHR anfällig für schmerzhafte, eitrige Sohlenballen-Geschwüre (Pododermatitis)! Nur bei extrem weicher, dicker Stroh-/Wiesenhaltung empfehlenswert.\n• DEUTSCHE RIESEN (7,0–11,0+ kg):\n  – Leistung & Gewicht: Zuchtreife erst spät (9–12 Monate!), enormer täglicher Futter- & Platzbedarf (mind. 4–6 m² pro Tier!).\n  – Verhaltensprofil: Sanfte Riesen, oft „wie kleine Hunde“.\n  – Anfälligkeiten (WARUM OFT UNGEEIGNET): Durch das extreme Körpergewicht sehr häufige Herz-Kreislauf-Probleme bei Sommerhitze, schmerzhafte wunde Läufe, Gelenkverschleiß und geringere Lebenserwartung (oft nur 4–6 Jahre statt 8–10). Für Hobby & Selbstversorgung sind Mittelrassen (3–5 kg) klar überlegen!',
