          'Im kühleren Schiefergebirge mit kürzerem Sommer entscheidet das Vorkeimen über den Ertrag:\n• VORKEIMEN (März bis Mitte April): Pflanzkartoffeln (nur zertifiziertes Pflanzgut wegen Viren!) einlagig in Eierkartons oder Kisten an einem hellen, kühlen Ort (10–14 °C) aufstellen -> bilden kräftige, grüne, kurze Lichtkeime (Vorsprung von 2–3 Wochen!).\n• PFLANZEN (Mitte April bis Anfang Mai): Erst wenn der Boden > 7–8 °C warm und abgetrocknet ist! Abstand ca. 35 cm in der Reihe, 65–70 cm Reihenabstand, ca. 8–10 cm tief.\n• ANHÄUFELN: Sobald das Laub 15–20 cm hoch ist, Erde von beiden Seiten zu einem Damm anhäufeln (und nach 2 Wochen wiederholen). Verhindert grüne, giftige Knollen und fördert den Knollenansatz.\n• KRAUT- & BRAUNFÄULE (Phytophthora infestans): Bei feuchtwarmem Sommerwetter Befall an dunklen, weißlich umrandeten Blattflecken erkennen -> befallenes Laub sofort abschneiden (in den Restmüll, NICHT auf den Kompost!), 14 Tage warten, bis die Schale der Knollen fest ist, dann erst roden.',
