          'Schnelle Diagnose am Blatt spart falsche Spritzungen:\n• ECHTER MEHLTAU („Schönwetterpilz“ — weißer, abwischbarer Belag AUF der Blattoberseite, oft an Zucchini, Erbsen, Rosen, Apfel im Hochsommer):\n  – Gegenmittel: 1 Teil frische Voll- oder Rohmilch (oder Molke) mit 8 Teilen Wasser mischen und alle 7 Tage tropfnass sprühen (Milchsäurebakterien/Lecithin verdrängen den Pilz!).\n• FALSCHER MEHLTAU („Schlechtwetterpilz“ — gelbe Flecken oben, grau-violetter Rasen UNTER dem Blatt bei Nässe/Kühle an Gurken, Zwiebeln, Wein, Salat):\n  – Gegenmittel: Milch hilft hier NICHT! Nur weite Pflanzabstände, trockenes Laub (morgens an der Wurzel gießen), Ackerschachtelhalm-Brühe vorbeugend und stark befallene Blätter sofort in den Restmüll.\n• GRAUSCHIMMEL (Botrytis — grauer pelziger Belag an Erdbeeren, Tomatenstielen, Salatherzen): Strohmulch unter Erdbeeren, morgens gießen, dichte Triebe auslichten.\n• BIRNENGITTERROST (leuchtend orange Flecken auf Birnenblättern): Kommt im Wechsel vom Zier-Wacholder der Umgebung -> schadet dem Birnbaum meist erst bei massivem Befall; befallenes Laub im Herbst entfernen.',
