          'Jahresfahrplan speziell angepasst an ca. 450–550 m Höhenlage im Thüringer Schiefergebirge:\n• JANUAR–FEBRUAR: Saatgut-Keimprobe & Einkauf; Obstbäume (nur Kernobst!) an frostfreien Tagen > -5 °C schneiden; Paprika/Chili ab Mitte Feb drinnen vorziehen; Steckhölzer von Beeren schneiden.\n• MÄRZ: Hochbeete abräumen & mit Kompost auffüllen; Erbsen, Dicke Bohnen, Spinat, Radieschen, Möhren und Knoblauch (wenn nicht im Herbst gesetzt) ins Freiland/Frühbeet; Tomaten Mitte/Ende März drinnen säen; Kartoffeln hell vorkeimen.\n• APRIL: Kartoffeln ab Mitte April setzen (wenn Boden > 7 °C); Zucchini/Kürbis/Gurken drinnen vorziehen; Kohl, Salat & Rote Bete ins Beet; Hühnerställe auf Milben prüfen & kalkanstrichen.\n• MAI: Ab 15.–20. Mai (nach den Eisheiligen!) Tomaten, Gurken, Zucchini, Bohnen & Kürbis rauspflanzen; Erdbeeren mit Stroh mulchen; Wiese nur abschnittsweise mähen (Insektenschutz).\n• JUNI: Ausgeizen, regelmäßig morgens gießen, Brennnesseljauche ansetzen, Beerennetze prüfen, Kirschen/Steinobst direkt nach Ernte schneiden, Rhabarber spätestens 24. Juni (Johanni) beenden.\n• JULI–AUGUST: Haupternte, Einkochen, Passata & Trocknen; ab August direkt nach Frühkartoffeln/Zwiebeln Feldsalat, Winterspinat, Postelein & Gründüngung (Phacelia) säen!\n• SEPTEMBER–OKTOBER: Herbstaussaat Winterknoblauch (Okt), Äpfel & Walnüsse ernten/trocknen, Leimringe gegen Frostspanner anbringen, Regentonnen & Pumpen vor erstem Frost ablassen!\n• NOVEMBER–DEZEMBER: Rosenkohl, Grünkohl & Pastinaken bei Frost ernten; leere Beete mit Laub/Kompost mulchen; Stall winterfest machen; Vögel sauber im Silo füttern.',
