          'Damit Hausmittel wirken und keine Blätter verbrennen, entscheiden genaue Dosierung und das richtige Wetter:\n• DIE 4 GOLDENE SPRITZ-REGELN:\n  1. NIEMALS in praller Sonne oder bei > 25 °C sprühen (Wassertropfen wirken sonst wie Brenngläser und Öle/Seifen verätzen Blätter!). Beste Zeit: abends kurz vor Sonnenuntergang oder bei bedecktem, windstillem Himmel.\n  2. IMMER Blattunterseiten mit einsprühen — dort sitzen Spinnmilben, Blattläuse, Weiße Fliege und viele Pilzsporen!\n  3. WEICHES WASSER NUTZEN: Regenwasser oder das weiche Schwarzatal-Leitungswasser (< 8,4 °dH) verhindert, dass Schmierseife ausflockt und verstopft.\n  4. PROBEBLATT-TEST: Bei empfindlichen Kulturen (junge Setzlinge, Gurken, Farnblättrige) erst 2 Blätter einsprühen und 24 Stunden warten.\n• UNTERSCHIED DER ANSÄTZE:\n  – KALTANSATZ (12–24 Std. in kaltem Wasser): gegen Insekten (z. B. Brennnessel-Kaltansatz).\n  – TEE / AUFGUSS (mit kochendem Wasser übergießen, abkühlen lassen): schnell gegen Milben, Läuse & Pilzanfang.\n  – BRÜHE / ABKOCHUNG (24 Std. einweichen, dann 20–30 Min. köcheln): löst feste Pflanzenstoffe wie Kieselsäure aus Ackerschachtelhalm!',
