        safetyWarning: 'Milchspritzungen im Gewächshaus nur bei guter Lüftung anwenden, da sonst bei dauerhafter Schwüle säuerliche Gerüche entstehen und Trauermücken angelockt werden können.',
        date: today,
        tags: ['Mehltau', 'Milch', 'Natron', 'Backpulver', 'Zucchini', 'Gurken', 'Hausmittel'],
