        content:
          'Wildpflanzen rund um Mellenbach-Glasbach ersetzen halbe Pflanzenschutzregale — wenn man die richtige Zubereitung wählt:\n• ACKERSCHACHTELHALM-BRÜHE (Nr. 1 gegen Pilze: Mehltau, Schorf, Rost, Braunfäule):\n  – 150 g frisches (oder 20 g getrocknetes) Kraut in 1 Liter Wasser 24 Std. einweichen, dann **20–30 Minuten leicht köcheln** (nur so löst sich die Kieselsäure!). Abseihen, **1:5 mit Wasser verdünnen** und vorbeugend ab Mai alle 10 Tage spritzen.\n• BRENNNESSEL-KALTANSATZ (Schnellhilfe gegen Blattläuse — NICHT vergären!):\n  – 100 g frische Brennnesseln auf 1 Liter kaltes Wasser nur **12–24 Stunden** ziehen lassen (bevor Gärung einsetzt!). Unverdünnt direkt auf Läuse sprühen (die frische Ameisensäure brennt Läuse weg).\n• KNOBLAUCH-ZWIEBEL-SUD (gegen Spinnmilben, Pilze & Grauschimmel):\n  – 40 g Knoblauch + 40 g Zwiebelschalen grob hacken, mit 1 Liter kochendem Wasser überbrühen, 3 Stunden ziehen lassen, abseihen und **1:3 verdünnt** spritzen.\n• RAINFARN- & WERMUT-TEE (gegen Kohlweißling, Erdflöhe, Ameisen, Rost):\n  – 30 g frisches Kraut auf 1 Liter kochendes Wasser, 15 Min. ziehen lassen, unverdünnt auf Zierpflanzen, Obst oder Kohl-Jungpflanzen sprühen.',
