        content:
          'Viele vermeintliche „Krankheiten“ an Tomate, Paprika oder Blattgemüse sind reine Pflege- oder Wasserfehler:\n• BLÜTENENDFÄULE (schwarze, ledrige, eingesunkene Spitze an der Unterseite von Tomaten/Paprika):\n  – URSACHE: KEIN Pilz, sondern akuter Calcium-Mangel in der Fruchtspitze — fast immer durch **ungleichmäßiges Gießen** (erst trocken, dann Schwall!) oder Überdüngung mit Kalium/Stickstoff (blockiert Calcium-Aufnahme!). Besonders häufig bei länglichen Sorten („San Marzano“).\n  – SOFORTHILFE: Gleichmäßig feucht halten + mulchen! Befallene Früchte abnehmen. Eierschalen auf dem Beet wirken erst nach Jahren — schneller hilft feinstes Algenkalk-/Urgesteinsmehl ins Gießwasser oder ein Blattdünger.\n• PLATZENDE TOMATEN / KOHL / MÖHREN: Kommt nach längerer Trockenheit ein plötzlicher starker Regenguss oder Gießschwall, schießt Wasser in die reife Frucht -> Schale platzt! Abhilfe: Mulchschicht + gleichmäßiges Gießen.\n• GELBE BLÄTTER RICHTIG DEUTEN:\n  – ÄLTERE Blätter gleichmäßig hellgrün/gelb = **Stickstoffmangel** -> Brennnesseljauche (1:10).\n  – ÄLTERE Blätter mit grünen Blattadern, dazwischen gelb („Marmorierung“) = **Magnesiummangel** (oft bei Tomaten) -> 1 TL Bittersalz auf 1 l Wasser sprühen.\n  – JÜNGSTE Triebspitzen gelb bei grünen Adern = **Eisenmangel** (Chlorose, z. B. durch zu hohen pH-Wert bei Heidelbeeren).',
