          'Mellenbach-Glasbach liegt mitten im Nationalen Geopark **Thüringer Schiefergebirge (Schieferland)** — geprägt von stark gefalteten Gesteinen des Erdaltertums:\n• DIE GESTEINE IM BODEN: Vorherrschend sind Tonschiefer, Kieselschiefer und Quarzite; oberhalb des Ortes finden sich zudem bekannte vulkanische Diabas-Aufschlüsse (ehem. Steinbruch).\n• BODEN-KONSEQUENZEN IM GARTEN:\n  – Schieferverwitterungsböden sind von Natur aus **kalkarm bis schwach sauer (ca. pH 5,2–6,2)**, eher flachgründig-steinig und im Hang gut wasserdurchlässig — speichern aber ohne Humus wenig Wasser und Nährstoffe!\n  – **SUPERKRAFT SCHIEFERSTEIN:** Dunkler Tonschiefer speichert tagsüber Sonnenwärme enorm stark und strahlt sie nachts langsam wieder ab! Eine einfache Trockenmauer oder eine Schieferplatten-Umrandung um wärmeliebende Kräuter (Rosmarin, Thymian) oder Erdbeeren hebt das Mikroklima um mehrere Grad!\n  – **DIABAS-URGESTEINSMEHL:** Vulkanisches Diabas-Mehl liefert genau die fehlenden Spurenelemente, Kieselsäure und Kalzium-Pufferung für unsere Schieferböden.',
