          'Im Dashboard und im Saisonkalender zeigt dir die App Angaben wie **„Vollherbst · Natur-Zeiger: Stieleiche (Fruchtreife & Laubfall)“** — das steckt dahinter:\n• WAS IST DIE PHÄNOLOGISCHE UHR? Der Deutsche Wetterdienst (DWD) teilt das Gartenjahr nicht nach starren Kalendertagen (wie „21. März = Frühling“), sondern in **10 natürliche biologische Jahreszeiten** ein! Denn im kalten Schiefergebirge auf 500 m fängt der Frühling oft 2–3 Wochen später an als im warmen Rheingraben — die Natur lügt nicht, der Kalender schon.\n• WARUM DIE STIELEICHE BEIM VOLLHERBST STEHT: Jede Phase hat eine feste **Zeigerpflanze** in der Natur, an der du draußen sofort erkennst, in welcher Phase wir gerade wirklich stecken:\n  – **Vorfrühling:** Haselblüte & Schneeglöckchen -> Zeit für Obstbaumschnitt & Fensterbank-Vorzucht.\n  – **Erstfrühling:** Forsythienblüte & Salweide -> Boden erwacht, Erbsen/Möhren/Spinat säen & Rosen schneiden.\n  – **Vollfrühling:** Apfelblüte & Flieder -> Kartoffeln legen, Frostgefahr beobachten.\n  – **Frühsommer:** Holunderblüte -> Wärmeliebendes (Tomaten, Bohnen, Kürbis) sicher nach draußen.\n  – **Hochsommer:** Sommerlinde & Frühapfelreife -> Haupternte & Einkochen.\n  – **Spätsommer:** Frühzwetschge & Heidekraut -> Gründüngung säen, Zwiebeln trocknen.\n  – **Frühherbst:** Holunderbeeren reif & Rosskastanie -> Lageräpfel & Kürbisse vor Frost bergen.\n  – **VOLLHERBST:** **Stieleiche (Eicheln werden reif & Laub fällt)** -> Jetzt ist die beste Pflanzzeit für neue Obstbäume, Winterknoblauch stecken, Beete abdecken & Wasserleitungen frostfest machen!\n  – **Winterruhe:** Keine Vegetation -> Ruhezeit, Saatgut-Tests & Planung.',
